1019	 * What this is for is the next unit — it is the measurement a declared
1020	 * difference has to be written from, and writing one from anything else is how
1021	 * a receipt ends up declaring a difference nobody measured.
1022	 */
1023	export const WITNESS_ANGULAR_SUPER_PRODUCTIVITY_MEASURED_STYLE_DIFFERENCES = Object.freeze([
1024		Object.freeze({
1025			label: 'header-icon-button',
1026			property: 'font-family',
1027			baseline: 'Roboto, "Helvetica Neue", sans-serif',
1028			migrated: 'Arial',
1029			why: 'the era lane resolves the button through Angular Material 8’s typography config; the MDC-based button in 16.2 sets no family on the host at all, so the element falls through to the user-agent default',
1030		}),
1031		Object.freeze({
1032			label: 'document-body',
1033			property: 'font-family',
1034			baseline: 'Roboto, "Helvetica Neue", sans-serif',
1035			migrated: 'Roboto, sans-serif',
1036			why: 'Angular Material’s default typography configuration dropped `"Helvetica Neue"` from the family list between 8.2 and 16.2',
1037		}),
1038	]);
1039	
1040	/** One lane's service-worker checkpoint, recorded from the browser. */
1041	export type WitnessAngularSuperProductivityServiceWorkerCheckpoint = {
1042		phase: 'before-interactions' | 'after-interactions' | 'after-online-reload';
1043		telemetry: WitnessServiceWorkerTelemetry;
1044	};
1045	
1046	/**
1047	 * A lane's whole service-worker record: the three checkpoints, the worker
1048	 * scripts the build actually shipped read before and after the run, and every
1049	 * worker-scoped event the browser reported.
1050	 */
1051	export type WitnessAngularSuperProductivityServiceWorker = {
1052		script: string;
1053		checkpoints: WitnessAngularSuperProductivityServiceWorkerCheckpoint[];
1054		/** The worker scripts the build emitted, read from the served tree. */
1055		outputFiles: Array<{ path: string; beforeSha256: string; afterSha256: string }>;
1056		workerEvents: WitnessServiceWorkerTelemetry['workerEvents'];
1057	};
1058	
1059	/** How the linked typeface degrades with the stylesheet answered in-context. */
1060	export type WitnessAngularSuperProductivityTypeface = {
1061		state: 'measured-typeface-degradation';
1062		cause: string;
1063		fontFaceDeclared: boolean;
1064		resolvedFontFamily: string;
1065		masked: false;
1066	};
1067	
1068	export type WitnessAngularSuperProductivityPersistenceEvidence = {
1069		store: 'browser-indexed-db-through-localforage';
1070		databaseName: 'SUP';
1071		storeName: 'SUP_STORE';
1072		backend: 'none';
1073		stubbed: false;
1074		/** The driver localforage settled on, recorded rather than pinned. */
1075		driverInUse: string;
1076		keysBeforeJourney: string[];
1077		keysAfterJourney: string[];
1078		localStorageKeysBeforeJourney: string[];
1079		localStorageKeysAfterJourney: string[];
1080		survivesOnlineReload: true;
1081	};
1082	
1083	/**
1084	 * The settled result of the task-list reorder, leg (b).
1085	 *
1086	 * The gesture is a genuine dragula pointer drag on the application's own task
1087	 * list, and what the shape pins is a RULE rather than a measured order: the
1088	 * task that moved is named, the rendered list before and after the move are
1089	 * both recorded, the after-order is a permutation of the before-order — nothing
1090	 * created or lost by moving one task — the order actually changed, and the
1091	 * order the application's own store settled to matches the order the page
1092	 * rendered. The literal titles and the from/to positions are measured by the
1093	 * calibration driver and pinned when this proof is published; this shape
1094	 * refuses a run whose store disagrees with its rendered list, or one that
1095	 * dropped or duplicated a task while moving one, or one whose "after" order is
1096	 * the "before" order unchanged.
1097	 */
1098	export type WitnessAngularSuperProductivityDrag = {
1099		state: 'measured-task-list-reorder';
1100		surface: (typeof WITNESS_REAL_APP_DRAG_SURFACES)[number];
1101		pointer: 'genuine-dragula-pointer-down-move-up';
1102		movedTask: string;
1103		renderedOrderBefore: string[];
1104		renderedOrderAfter: string[];
1105		storeOrderAfter: string[];
1106	};
1107	
1108	/**
1109	 * The settled result of starting and stopping a task's timer, leg (c),
1110	 * re-anchored after the u20c2j calibration contradicted the first shape.
1111	 *
1112	 * The anchor is the header's own global play button. Starting the timer through
1113	 * it flips the button's `mat-icon` from `play_arrow` to `pause` and sets exactly
1114	 * one current task; stopping it flips the icon back and clears the current task.
1115	 * The shape pins the RULE the calibration measured on both lanes rather than the
1116	 * literal icons: the before- and after-start icons differ (the flip), the
1117	 * after-stop icon returns to the before-start icon (the round trip), starting
1118	 * set one current task and stopping cleared it. The exact icon names are
1119	 * recorded on {@link WITNESS_ANGULAR_SUPER_PRODUCTIVITY_TIME_TRACKING_REANCHOR}.
1120	 *
1121	 * The first shape carried two sub-rules the live application contradicted and
1122	 * they are gone: it required a per-task `.play-icon-indicator` to be present,
1123	 * and a `.time-val` carrying a digit. Both are recorded as truthful non-claims
1124	 * on the re-anchor constant — the application's `ms-to-string` hides sub-minute
1125	 * durations so a journey's `.time-val` is always `-`, and the per-task
1126	 * `.start-task-btn` is hover-gated and never visible to a click, which is why
1127	 * the timer is driven through the header rather than the task.
1128	 */
1129	export type WitnessAngularSuperProductivityTimeTracking = {
1130		state: 'measured-task-time-tracking';
1131		control: 'main-header .play-btn mat-icon';
1132		iconBeforeStart: string;
1133		iconAfterStart: string;
1134		iconAfterStop: string;
1135		currentTasksOnStart: number;
1136		currentTasksOnStop: number;
1137	};
1138	
1139	/**
1140	 * The settled result of the settings-change, leg (d) — the last journey leg.
1141	 *
1142	 * Three measured parts, each a RULE rather than a pinned literal, because the
1143	 * one lane-divergent part (the theme rgb) is a declared difference and the rest
1144	 * is measured the same in both lanes:
1145	 *
1146	 *  - `projectSwitch`: the create grew the side-nav list by exactly one, and the
1147	 *    switch flipped the current-project title to the project the create named —
1148	 *    `currentTitleAfter` equals `newProjectTitle` and differs from
1149	 *    `currentTitleBefore`. The literal titles are measured and travel, because
1150	 *    they are the application's own and agree across lanes.
1151	 *  - `theme`: the driven `huePrimary` mat-select change shifted the measured
1152	 *    `styleVar` — `styleValueBefore` differs from `styleValueAfter`. The literal
1153	 *    rgb values are per-lane and may differ (the declared lane difference on
1154	 *    {@link WITNESS_ANGULAR_SUPER_PRODUCTIVITY_SETTINGS}); the parity digest
1155	 *    carries only the fact THAT the driven change shifted the var, not the value.
1156	 *  - `shortcut`: `w` brought the work view — its host tag rendered after the
1157	 *    press. The `b` non-claim is recorded on the settings constant.
1158	 */
1159	export type WitnessAngularSuperProductivitySettings = {
1160		state: 'measured-settings-change';
1161		projectSwitch: {
1162			control: string;
1163			dialog: string;
1164			titleControl: string;
1165			switchControl: string;
1166			newProjectTitle: string;
1167			currentTitleBefore: string;
1168			currentTitleAfter: string;
1169			projectCountBefore: number;
1170			projectCountAfter: number;
1171		};
1172		theme: {
1173			autoContrastControl: string;
1174			control: string;
1175			styleVar: string;
1176			styleValueBefore: string;
1177			styleValueAfter: string;
1178		};
1179		shortcut: {
1180			key: string;
1181			hostTag: string;
1182			hostTagPresentAfter: number;
1183		};
1184	};
1185	
1186	/**
1187	 * The application-specific journey evidence.
1188	 *
1189	 * `typeface` and `persistence` are the facts legs (a) and (e) measure and are
1190	 * always present. `drag` (leg b), `timeTracking` (leg c) and `settings` (leg d)
1191	 * are the legs this journey drives: the parser requires all three once a browser
1192	 * has driven the journey, but they are typed optional so a producer can populate
1193	 * them without the not-yet-updated wiring failing to compile.
1194	 */
1195	export type WitnessAngularSuperProductivityJourney = {
1196		typeface: WitnessAngularSuperProductivityTypeface;
1197		persistence: WitnessAngularSuperProductivityPersistenceEvidence;
1198		drag?: WitnessAngularSuperProductivityDrag;
1199		timeTracking?: WitnessAngularSuperProductivityTimeTracking;
1200		settings?: WitnessAngularSuperProductivitySettings;
1201	};
1202	
1203	/**
1204	 * The scroll reading, as a union rather than a pinned shape.
1205	 *
1206	 * This application pins a drawer container to the viewport and scrolls inner
1207	 * panels, and it also renders long task lists; which of the two a route
1208	 * actually produces is a measurement, and both outcomes are honest evidence.
1209	 * What the schema refuses is a run that carries neither, and a lane pair that
1210	 * disagrees about which one it is.
1211	 */
1212	export type WitnessAngularSuperProductivityScroll =
1213		| WitnessScrollSurface
1214		| WitnessMeasuredScrollAbsence;
1215	
1216	export type WitnessAngularSuperProductivityRun = WitnessRealAppRun & {
1217		serviceWorker: WitnessAngularSuperProductivityServiceWorker;
1218		consoleErrorInventory: WitnessConsoleErrorInventory;
1219		failedRequestInventory: WitnessFailedRequestInventory;
1220		mockedNonLoopbackSeams: WitnessMockedNonLoopbackSeamInventory;
1221		renderedStyles: WitnessRenderedStyleEvidence;
1222		applicationJourney: WitnessAngularSuperProductivityJourney;
1223		scroll: WitnessAngularSuperProductivityScroll;
1224		behaviorDigest: string;
1225	};
1226	
1227	export type WitnessAngularSuperProductivityMutation = {
1228		failure: 'witness-semantic-assertion';
1229		intendedFailure: true;
1230		lane: 'baseline' | 'migrated';
1231		seam: string;
1232		path: string;
1233		offset: number;
1234		beforeSha256: string;
1235		mutatedSha256: string;
1236		afterRestoreSha256: string;
1237		restoredByteIdentically: true;
1238		restoredRun: 'pass';
1239		restoredBehaviorDigest: string;
1240	};
1241	
1242	export type WitnessAngularSuperProductivityReceipt = {
1243		schemaVersion: typeof WITNESS_ANGULAR_SUPER_PRODUCTIVITY_SCHEMA;
1244		result: 'pass';
1245		fixture: typeof ANGULAR_SUPER_PRODUCTIVITY_FIXTURE;
1246		source: typeof ANGULAR_SUPER_PRODUCTIVITY_SOURCE;
1247		provenance: Record<string, unknown>;
1248		canonicalReceipts: typeof ANGULAR_SUPER_PRODUCTIVITY_CANONICAL_RECEIPTS;
1249		determinism: typeof WITNESS_ANGULAR_SUPER_PRODUCTIVITY_DETERMINISM;
1250		sassRandomBoundary: typeof WITNESS_ANGULAR_SUPER_PRODUCTIVITY_SASS_RANDOM_BOUNDARY;
1251		runs: WitnessAngularSuperProductivityRun[];
1252		mutation: WitnessAngularSuperProductivityMutation;
1253		consoleErrors: Readonly<
1254			Record<'baseline' | 'migrated', readonly WitnessConsoleErrorInventoryEntry[]>
1255		>;
1256		failedRequests: Readonly<
1257			Record<'baseline' | 'migrated', readonly WitnessFailedRequestInventoryEntry[]>
1258		>;
1259		/**
1260		 * The exact per-lane seam membership as published. Both halves are held to
1261		 * the one shared declaration, because both emitted documents carry the same
1262		 * stylesheet link and a lane that asked for something else would mean the
1263		 * offline-faithful rebuild did not hold.
1264		 */
1265		mockedSeams: Record<'baseline' | 'migrated', WitnessMockedNonLoopbackSeamEntry[]>;
1266		fontSeam: typeof WITNESS_ANGULAR_SUPER_PRODUCTIVITY_FONT_SEAM;
1267		serviceWorker: typeof WITNESS_ANGULAR_SUPER_PRODUCTIVITY_SERVICE_WORKER;
1268		/** What each lane's worker settled to, as its own runs measured it. */
1269		serviceWorkerParity: Record<
1270			'baseline' | 'migrated',
1271			{
1272				registeredScriptPath: string;
1273				scope: string;
1274				activeAtFinalCheckpoint: string;
1275				controlledAtFinalCheckpoint: boolean;
1276				cacheNames: string[];
1277			}
1278		>;
1279		migratedLaneChain: typeof ANGULAR_SUPER_PRODUCTIVITY_MIGRATED_LANE_CHAIN;
1280		migrationFindings: typeof WITNESS_ANGULAR_SUPER_PRODUCTIVITY_MIGRATION_FINDINGS;
1281		typefaceDegradations: Record<
1282			'baseline' | 'migrated',
1283			WitnessAngularSuperProductivityTypeface
1284		>;
1285		renderedStyleParity: {
1286			state: 'measured-resolved-styles-with-declared-differences';
1287			probes: number;
1288			rule: typeof WITNESS_ANGULAR_SUPER_PRODUCTIVITY_STYLE_DIFFERENCE_RULE;
1289			declaredDifferences: Array<{ label: string; why: string }>;
1290			otherProbesAgree: true;
1291		};
1292		persistence: typeof WITNESS_ANGULAR_SUPER_PRODUCTIVITY_PERSISTENCE;
1293		routeShape: typeof WITNESS_ANGULAR_SUPER_PRODUCTIVITY_ROUTE_SHAPE;
1294		scroll: WitnessAngularSuperProductivityScroll;
1295		accommodations: typeof WITNESS_ANGULAR_SUPER_PRODUCTIVITY_ACCOMMODATIONS;
1296		accommodationPayload: typeof WITNESS_ANGULAR_SUPER_PRODUCTIVITY_ACCOMMODATION_PAYLOAD;
1297		dragSurface: typeof WITNESS_ANGULAR_SUPER_PRODUCTIVITY_DRAG_SURFACE;
1298		readiness: {
1299			angularLineage: { ready: number; total: number; counted: false };
1300			overall: { ready: number; total: number };
1301		};
1302		locality: {
1303			mode: 'offline';
1304			successfulNonLoopback: 0;
1305			osWideIsolation: false;
1306			mockedNonLoopbackSeams: number;
1307		};
1308		nonclaims: string[];
1309		integrity: { algorithm: 'sha256'; canonicalDigest: string };
1310	};
1311	
1312	const exact = (left: unknown, right: unknown): boolean =>
1313		canonicalize(left) === canonicalize(right);
1314	
1315	const sha256Digest = (value: unknown): boolean => typeof value === 'string' && value.length === 64;
1316	
1317	const sortedUnique = (values: string[]): boolean =>
1318		Array.isArray(values) &&
1319		values.join('\n') === [...values].sort().join('\n') &&
1320		new Set(values).size === values.length;
1321	
1322	export function witnessAngularSuperProductivityRawDigest(
1323		run: WitnessAngularSuperProductivityRun | WitnessRealAppRun,
1324	): string {
1325		const { pass: _pass, result: _result, semanticDigest: _semanticDigest, ...raw } = run;
1326		const withoutBehavior = { ...raw } as Record<string, unknown>;
1327		delete withoutBehavior.behaviorDigest;
1328		return sha256(canonicalize(withoutBehavior));
1329	}
1330	
1331	/**
1332	 * The rendered-style projection that participates in the parity digest: the
1333	 * probes the lanes must agree on, in full, plus the LABELS of the ones the
1334	 * receipt declares they disagree on. Folding the declared-difference values in
1335	 * would make the two lanes disagree about a difference the receipt already
1336	 * records; dropping the labels would let a probe leave the declaration
1337	 * unnoticed.
1338	 */
1339	function renderedStyleProjection(
1340		evidence: WitnessRenderedStyleEvidence | undefined,
1341		declaredDifferenceLabels: readonly string[],
1342	): unknown {
1343		const differing = new Set(declaredDifferenceLabels);
1344		return {
1345			state: evidence?.state,
1346			// The label, selector and resolved CSS properties of every probe the two
1347			// lanes agree on — but NOT the measured pixel geometry.
1348			// `assertRenderedStyleDifferences` defines rendered-style parity as an
1349			// equality of `properties` alone, and the declared-difference mechanism can
1350			// only speak about a probe whose properties differ. The width and height are
1351			// lane-dependent rendered appearance rather than behaviour: this application
1352			// lifts across Angular Material's pre-MDC→MDC rewrite, which moves the toolbar
1353			// height (measured u20c2q: 48 in the era lane, 56 in the migrated one) and the
1354			// scrollbar-driven side-nav width by a few pixels (199 against 196) while
1355			// every CSS property the probes read resolves identically in both lanes.
1356			// Since the probes' properties agree they cannot be declared differences, and
1357			// folding their geometry into the shared digest would make it disagree about a
1358			// difference the schema's own style-parity check deliberately ignores. The
1359			// geometry stays in the run (and `assertRenderedStyles` still bounds it
1360			// non-negative per probe); only the behaviour projection drops it.
1361			agreeing: (evidence?.probes ?? [])
1362				.filter((probe) => !differing.has(probe.label))
1363				.map((probe) => ({
1364					label: probe.label,
1365					selector: probe.selector,
1366					properties: probe.properties,
1367				})),
1368			declaredDifferenceLabels: (evidence?.probes ?? [])
1369				.map((probe) => probe.label)
1370				.filter((label) => differing.has(label)),
1371		};
1372	}
1373	
1374	/**
1375	 * Lane-independent behavior projection.
1376	 *
1377	 * Production bytes are lane-specific by construction — eight majors of bundler
1378	 * apart — so the byte inventory stays in the run and out of this digest. So do
1379	 * the things this migration genuinely changed: the declared style differences,
1380	 * and each lane's own service-worker version and cache identity, which name
1381	 * hashed bundles that cannot be the same in two lanes. What is left is
1382	 * everything the two lanes must agree on, including the settled state of the
1383	 * worker at each checkpoint, what the store held, and what the browser resolved
1384	 * for the typeface neither lane is served.
1385	 */
1386	export function witnessAngularSuperProductivityBehaviorDigest(
1387		run: WitnessAngularSuperProductivityRun | WitnessRealAppRun,
1388		declaredDifferenceLabels: readonly string[] = [],
1389	): string {
1390		const typed = run as WitnessAngularSuperProductivityRun;
1391		const journey = typed.applicationJourney as
1392			| WitnessAngularSuperProductivityJourney
1393			| undefined;
1394		const seams = run.mockedNonLoopbackSeams;
1395		return sha256(
1396			canonicalize({
1397				app: run.app,
1398				framework: run.framework,
1399				interactions: run.interactions,
1400				assertions: run.assertions,
1401				routes: run.routes,
1402				trackedEvents: run.trackedEvents,
1403				witnessRecord: run.witnessRecord,
1404				cleanPage: run.cleanPage,
1405				offlineEvidence: run.offlineEvidence,
1406				servedStaticPolicy: {
1407					transport: run.servedStatic.transport,
1408					documentFallback: run.servedStatic.documentFallback,
1409					missingAssets: run.servedStatic.missingAssets,
1410					traversal: run.servedStatic.traversal,
1411					byteIdentical: run.servedStatic.byteIdentical,
1412					hmrControls: run.servedStatic.hmrControls,
1413					serviceWorkerScripts: run.servedStatic.serviceWorkers.length,
1414				},
1415				// The membership is checked exactly per lane against the published
1416				// inventory; only the policy and the accounting travel, exactly as the
1417				// mocked-seam membership does, because each framework reports its own
1418				// diagnostics in its own words.
1419				consoleErrorPolicy: {
1420					policy: run.consoleErrorInventory?.policy,
1421					originPlaceholder: run.consoleErrorInventory?.originPlaceholder,
1422					outsideInventory: run.consoleErrorInventory?.outsideInventory,
1423					entries: run.consoleErrorInventory?.observed.length,
1424					total: run.consoleErrorInventory?.total,
1425				},
1426				failedRequestPolicy: {
1427					policy: run.failedRequestInventory?.policy,
1428					outsideInventory: run.failedRequestInventory?.outsideInventory,
1429					entries: run.failedRequestInventory?.observed.length,
1430					total: run.failedRequestInventory?.total,
1431				},
1432				// The settled half of the registration, which both lanes must agree on:
1433				// what was registered, installing, waiting, controlling and cached at
1434				// each checkpoint. The version identity and the cache CONTENTS name
1435				// hashed bundles and stay in the run.
1436				serviceWorkerSettled: {
1437					script: typed.serviceWorker?.script,
1438					outputFiles: (typed.serviceWorker?.outputFiles ?? []).map((file) => file.path),
1439					checkpoints: (typed.serviceWorker?.checkpoints ?? []).map((checkpoint) => ({
1440						phase: checkpoint.phase,
1441						state: checkpoint.telemetry.state,
1442						registered: checkpoint.telemetry.registration.scriptPath !== null,
1443						installing: checkpoint.telemetry.registration.installing,
1444						waiting: checkpoint.telemetry.registration.waiting,
1445						active: checkpoint.telemetry.registration.active,
1446						controlled: checkpoint.telemetry.controller !== null,
1447						caches: checkpoint.telemetry.cacheNames.length,
1448					})),
1449				},
1450				mockedSeamPolicy: {
1451					policy: seams?.policy,
1452					pathPolicy: seams?.pathPolicy,
1453					outsideInventory: seams?.outsideInventory,
1454					successfulNonLoopback: seams?.successfulNonLoopback,
1455					members: seams?.category.length,
1456					observed: seams?.observed.length,
1457					absent: seams?.absent.length,
1458				},
1459				renderedStyles: renderedStyleProjection(run.renderedStyles, declaredDifferenceLabels),
1460				typeface: {
1461					state: journey?.typeface.state,
1462					fontFaceDeclared: journey?.typeface.fontFaceDeclared,
1463					resolvedFontFamily: journey?.typeface.resolvedFontFamily,
1464					masked: journey?.typeface.masked,
1465				},
1466				persistence: {
1467					store: journey?.persistence.store,
1468					databaseName: journey?.persistence.databaseName,
1469					storeName: journey?.persistence.storeName,
1470					backend: journey?.persistence.backend,
1471					stubbed: journey?.persistence.stubbed,
1472					driverInUse: journey?.persistence.driverInUse,
1473					keysBeforeJourney: journey?.persistence.keysBeforeJourney,
1474					keysAfterJourney: journey?.persistence.keysAfterJourney,
1475					localStorageKeysBeforeJourney: journey?.persistence.localStorageKeysBeforeJourney,
1476					localStorageKeysAfterJourney: journey?.persistence.localStorageKeysAfterJourney,
1477					survivesOnlineReload: journey?.persistence.survivesOnlineReload,
1478				},
1479				// Legs (b) and (c) are behavioural, so both lanes must agree on the
1480				// settled reorder and the timer flip in full; they travel here rather
1481				// than staying in the lane-specific byte inventory.
1482				drag: {
1483					state: journey?.drag?.state,
1484					surface: journey?.drag?.surface,
1485					pointer: journey?.drag?.pointer,
1486					movedTask: journey?.drag?.movedTask,
1487					renderedOrderBefore: journey?.drag?.renderedOrderBefore,
1488					renderedOrderAfter: journey?.drag?.renderedOrderAfter,
1489					storeOrderAfter: journey?.drag?.storeOrderAfter,
1490				},
1491				timeTracking: {
1492					state: journey?.timeTracking?.state,
1493					control: journey?.timeTracking?.control,
1494					iconBeforeStart: journey?.timeTracking?.iconBeforeStart,
1495					iconAfterStart: journey?.timeTracking?.iconAfterStart,
1496					iconAfterStop: journey?.timeTracking?.iconAfterStop,
1497					currentTasksOnStart: journey?.timeTracking?.currentTasksOnStart,
1498					currentTasksOnStop: journey?.timeTracking?.currentTasksOnStop,
1499				},
1500				// Leg (d) is behavioural, and both lanes must agree on it — but the theme
1501				// rgb it shifts is a declared lane difference, so only the FACT of the
