274			expect(timer.iconProbe.group).toBe('main-header .play-btn');
275			expect(timer.currentTask).toBe('task.isCurrent');
276			expect(timer.iconBeforeStart).toBe('play_arrow');
277			expect(timer.iconAfterStart).toBe('pause');
278			// A round trip: the stop returns the control to its resting icon.
279			expect(timer.iconAfterStop).toBe(timer.iconBeforeStart);
280			expect(timer.iconAfterStart).not.toBe(timer.iconBeforeStart);
281			// The two dropped sub-rules are recorded as truthful non-claims, per mw1e.
282			expect(reanchor.corrected).toEqual([
283				'per-task-play-icon-indicator-present',
284				'per-task-time-val-carries-a-digit',
285			]);
286			expect(reanchor.measuredIconBeforeStart).toBe(timer.iconBeforeStart);
287			expect(reanchor.measuredIconAfterStart).toBe(timer.iconAfterStart);
288			expect(reanchor.measuredCurrentTasksOnStart).toBe(1);
289			expect(reanchor.measuredCurrentTasksOnStop).toBe(0);
290			expect(reanchor.subMinuteTimeValueHidden.length).toBeGreaterThan(0);
291			expect(reanchor.perTaskStartButtonHoverGated.length).toBeGreaterThan(0);
292			expect(reanchor.published).toBe(false);
293			expect(reanchor.masked).toBe(false);
294		});
295	
296		it('pins leg (d): the project-switch spine, a driven theme control, and the `w` shortcut', () => {
297			const leg = journey.settingsChange;
298			const settings = WITNESS_ANGULAR_SUPER_PRODUCTIVITY_SETTINGS;
299			// The project-switch spine: the addProject control, the dialog, the switch,
300			// and the count growing one to two.
301			expect(leg.projectSwitch.addControl).toBe(settings.projectSwitch.addControl);
302			expect(leg.projectSwitch.dialog).toBe('dialog-create-project');
303			expect(leg.projectSwitch.titleInput).toContain(':not([type=color])');
304			expect(leg.projectSwitch.switchControl).toContain('.project:nth-of-type(2)');
305			expect(leg.projectSwitch.titleControl).toBe('main-header .current-project-title');
306			expect(leg.projectSwitch.projectCountAfter).toBe(leg.projectSwitch.projectCountBefore + 1);
307			expect(leg.projectSwitch.newProjectTitle.length).toBeGreaterThan(0);
308			expect(leg.projectSwitch.currentTitleBefore).not.toBe(leg.projectSwitch.newProjectTitle);
309			// The theme control is the click-driveable mat-select, NOT the untouchable
310			// color input, and it is measured against a contrast custom property.
311			expect(leg.theme.control).toContain('mat-select');
312			expect(leg.theme.control).not.toContain('input[type=color]');
313			expect(leg.theme.autoContrastControl).toContain('mat-checkbox');
314			expect(leg.theme.styleVar).toBe('--palette-primary-contrast-50');
