317			expect(leg.shortcut.key).toBe('w');
318			expect(leg.shortcut.hostTag).toBe(journey.hostTag);
319		});
320	
321		it('records the color-input non-claim and the theme lane difference as measurements', () => {
322			const settings = WITNESS_ANGULAR_SUPER_PRODUCTIVITY_SETTINGS;
323			expect(settings.state).toBe('measured-settings-change');
324			// u20c2l: the native color input is undriveable, so no color-save shift is
