328			// The shifted rgb differs across lanes, and that is a declared difference,
329			// not a failure: baseline emits a bare triple, migrated an rgba().
330			expect(settings.theme.measuredBaselineBefore).not.toBe(settings.theme.measuredMigratedBefore);
331			expect(settings.theme.measuredBaselineBefore).not.toBe(settings.theme.measuredBaselineAfter);
332			expect(settings.theme.measuredMigratedBefore).not.toBe(settings.theme.measuredMigratedAfter);
333			expect(settings.theme.laneDifference.length).toBeGreaterThan(0);
334			// The `b` shortcut had no visible toggle in the observed state, recorded as
335			// a measured limitation rather than claimed as an effect.
336			expect(settings.shortcut.backlogToggleNonClaim.length).toBeGreaterThan(0);
337			expect(settings.shortcut.key).toBe('w');
338			expect(settings.published).toBe(false);
339			expect(settings.masked).toBe(false);
