354		it('carries the reader-ordering correction the same way', () => {
355			const correction = WITNESS_ANGULAR_SUPER_PRODUCTIVITY_KEY_ORDER_CORRECTION;
356			expect(correction.correction).toBe('utf16-code-unit');
357			// The three keys the collator and code-unit order disagree about are all in
358			// the census this journey pins, which is how the contradiction surfaced.
359			for (const key of correction.disagreedOn)
360				expect([...journey.keysAfterJourney]).toContain(key);
