384			// The fixed probe list every vertical measures is untouched — the leg-(d)
385			// custom property is not a property any fixed probe reads, so the two-phase
386			// reading cannot disturb the end-of-journey measurement.
387			const themeVar = journey.settingsChange.theme.styleVar;
