5264	
5265	/** The migrated build record this proof serves, bound by the sha256 of its bytes. */
5266	const SUPER_PRODUCTIVITY_BOUND_MIGRATED = ANGULAR_SUPER_PRODUCTIVITY_CANONICAL_RECEIPTS.find(
5267		(bound) => bound.lane === 'migrated',
5268	);
5269	if (SUPER_PRODUCTIVITY_BOUND_MIGRATED === undefined)
5270		throw new Error('Super Productivity bound migrated build record is absent');
5271	
5272	const angularSuperProductivitySpec: AppSpec = {
5273		app: ANGULAR_SUPER_PRODUCTIVITY_APP,
5274		canonicalReceipt: SUPER_PRODUCTIVITY_BOUND_MIGRATED.path,
5275		/**
5276		 * The bound record publishes a top-level `digest` over its own content rather
5277		 * than an `integrity.canonicalDigest`, so the honest binding is the sha256 of
5278		 * its exact bytes — the same value the receipt schema binds it by.
5279		 */
5280		canonicalDigest: SUPER_PRODUCTIVITY_BOUND_MIGRATED.sha256,
5281		canonicalBinding: 'file-sha256',
5282		framework: 'angular',
5283		sources: {
5284			baseline: '.versionless/cache/angular-super-productivity-v2-13-15-baseline/dist-run2',
5285			migrated: '.versionless/stage/angular-super-productivity-v2-13-15-u18b/dist-25',
5286		},
5287		/**
5288		 * Deep-linked rather than opened bare. The bare document records its
5289		 * navigation as `#/`, which the router resolves through its `**` route onto
5290		 * the work view — a route the application does not declare, and one the
5291		 * receipt schema refuses as a recorded navigation. Asking for the declared
5292		 * route is what makes the recorded navigation a declared one.
5293		 */
5294		initialRoute: SUPER_PRODUCTIVITY_JOURNEY.initialRoute,
